  insert into public.brands (name, website, description, country, status) values ('ZIIP', 'https://ziipbeauty.co.uk', 'At-home beauty-device brand behind the ZIIP HALO microcurrent/nanocurrent device, founded by electrical esthetician Melanie Simon and David Mason. Its affiliate program runs on Awin (US) at a 10% default commission with a 30-day cookie, and the brand''s own affiliates page supports media, content creators and skincare enthusiasts with gifting and VIP launch access. No earnings cap statement is published, so the cap stays unknown.', 'United States', 'published') returning id into bid;
