  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ziipbeauty.co.uk/pages/affiliates', 'brand_site', 'ugc_program', 'The brand''s own affiliates page (UK storefront) supports media, content creators and skincare enthusiasts promoting the ZIIP HALO, with gifting and VIP launch access, and publishes the partnerships email partnerships@ziipbeauty.com. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 12, 13, 9, 5, '{"compensation": "10% default commission on a premium device is mid-range; no cap statement is published, so the cap is honestly unknown.", "contact_access": "A published partnerships email on the brand''s own affiliates page, plus the Awin application route.", "credibility": "Established beauty-tech brand founded by a named electrical esthetician, with a full Awin program profile.", "niche_fit": "A demonstrable at-home facial device is ideal before/after and routine UGC material.", "opportunity_availability": "Open application through Awin, subject to network approval.", "ugc_evidence": "The brand''s own affiliates page explicitly supports content creators with gifting and VIP launch access."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FaceTory', 'https://www.facetory.com', 'K-beauty sheet-mask and skincare brand. Its own Influencer Commission Opportunity page routes influencers into a Refersion dashboard with a personalized link; the current published offer pays a flat $7 per order generated for the free Spot Fighters promo, stated to run for an indefinite period. A directory listing instead shows 10% via Impact, which conflicts with the brand page''s flat promo, so commission_rate is recorded as null with the flat documented. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliate@facetory.com', null, null, 'needs_review', null);
