  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FaceTory Influencer Commission Program (Refersion)', 'https://www.facetory.com/pages/influencer-commission-opportunity', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facetory.com/pages/influencer-commission-opportunity', 'brand_site', 'affiliate_program', 'FaceTory''s own influencer commission page explains that influencers log into a Refersion dashboard for a personalized affiliate link and publishes the contact email affiliate@facetory.com for questions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facetory.com/pages/influencer-commission-opportunity', 'brand_site', 'commission_rate', 'The brand''s own page states the current offer pays a flat $7 per order generated for the free Spot Fighters promo, for an indefinite period of time — a flat bounty, recorded as flat. LinkClicky separately lists FaceTory at 10% via Impact, which conflicts with the brand page''s flat promo and Refersion route, so commission_rate is recorded as null rather than guessed. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 9, 12, 9, 4, '{"compensation": "The only brand-published pay is a flat $7 per order on a promo, and a directory''s 10% Impact listing conflicts, so the rate is null and compensation scored cautiously; cap unknown.", "contact_access": "A published affiliate email on the brand''s own program page, plus the page''s own sign-up route.", "credibility": "Established K-beauty DTC brand with a long-running storefront and subscription business.", "niche_fit": "Sheet masks and spot patches are classic, highly visual skincare UGC products.", "opportunity_availability": "Open sign-up from the brand''s own influencer page into Refersion.", "ugc_evidence": "A brand-run influencer commission page with personalized links and a dashboard, aimed directly at creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cammellatte', 'https://cammellatte.com', 'Natural skincare brand built on camel milk (soaps, body butter, hand cream), founded by a husband-and-wife team, produced in Israel and shipped from a Michigan warehouse. Its own Affiliates page recruits social influencers, bloggers and vloggers: commissions start at 10% on all sales with room to increase the rate based on sales, a dedicated program manager, freebies and early product access, and no fee to join. The 10% starting rate is recorded. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'hello@cammellatte.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Cammellatte Affiliate Program)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://cammellatte.com/pages/affiliates.', 'https://cammellatte.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cammellatte Affiliate Program', 'https://cammellatte.com/pages/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cammellatte.com/pages/affiliates', 'brand_site', 'affiliate_program', 'Cammellatte''s own Affiliates page (''We''d love for you to join our Cammellatte Affiliate Program'') recruits social influencers, bloggers and vloggers with a passion for clean beauty: post a customized link, earn commission on resulting sales, with a dedicated program manager, affiliate-exclusive discounts, freebies, unreleased-product access and contests. The page publishes the contact email hello@cammellatte.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cammellatte.com/pages/affiliates', 'brand_site', 'commission_rate', 'The brand''s own page states ''You''ll earn commissions starting at 10% on all Cammellatte sales generated through your connections'' and ''You''ll have room to regularly increase your commission rate based on sales you make.'' The 10% starting rate is recorded. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 12, 12, 9, 4, '{"compensation": "10% starting commission with published room to increase is fair; no cap statement is published, so the cap is honestly unknown.", "contact_access": "A published contact email on the program page plus a named dedicated program manager.", "credibility": "Operating DTC brand with a detailed program page, 11,000+ customers claimed on its storefront and US warehouse shipping.", "niche_fit": "A distinctive single-ingredient skincare story (camel milk) gives creators a clear content angle for mature-skin routines.", "opportunity_availability": "Open application from the brand''s own page, no fee to join.", "ugc_evidence": "The program page speaks directly to influencers, bloggers and vloggers with freebies and early access; no measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PATTERN Beauty', 'https://patternbeauty.com', 'Premium haircare and styling brand for curly, coily and tight-textured hair, founded by Tracee Ellis Ross. Awin''s own case study confirms PATTERN''s affiliate program ran on Awin through 2025 (agency Wellblūm), pivoting from discount-led volume to content partners and growing revenue +101% YoY by July 2025. The only published rate is an older directory listing (ShareASale, 8%, March 2024) from the pre-Awin era, and no current Awin rate is published, so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.awin.com/us/case-studies/pattern-revenue-growth.', 'https://www.awin.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PATTERN Beauty Affiliate Program (Awin)', 'https://www.awin.com', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.awin.com/us/case-studies/pattern-revenue-growth', 'affiliate_network', 'affiliate_program', 'Awin''s own case study (''How Content Focus Led to +101% Revenue at PATTERN Beauty'') confirms PATTERN Beauty''s affiliate program ran on Awin through 2025 with agency Wellblūm: at the start of 2025 the program pivoted from discount-led partners to Awin''s pool of content partners, reaching +101% YoY revenue by July 2025 with sustained double-digit AOV growth.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/pattern-beauty/', 'affiliate_directory', 'commission_rate', 'LinkClicky''s listing (last updated March 2024) records PATTERN Beauty on ShareASale at 8% per sale with a 30-day cookie — the pre-Awin network era. No current Awin-era rate is published in any fetched source, so commission_rate is recorded as null rather than carrying the stale figure forward. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 8, 5, 8, 5, '{"compensation": "No current rate is published \u2014 only a stale 2024 ShareASale-era 8% listing \u2014 so the rate is null and compensation scored down; cap unknown.", "contact_access": "No public program email is published; contact runs through the Awin application and its agency.", "credibility": "Major celebrity-founded haircare brand with national retail presence and a network-published growth case study.", "niche_fit": "Textured-hair routines, wash-day and styling content are core high-engagement beauty UGC.", "opportunity_availability": "Program live on Awin per the network''s own case study; application runs through the network.", "ugc_evidence": "The Awin case study documents a deliberate pivot to content partners and editorial partnerships, with campaign deliverables including Instagram posts and Stories."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bondi Body', 'https://bondi-body.com', 'At-home beauty-tech brand (Australian-founded, UK storefront) selling IPL hair-removal devices, including the V2 handset named best IPL device by Good Housekeeping Institute testing. Its Awin affiliate programme pays 4% commission on all sales (new and existing customers) with a 30-day cookie and a £190 average order value, plus dedicated affiliate support. No earnings cap statement is published, so the cap stays unknown.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'katherine@profectmarketing.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/55221.', 'https://ui.awin.com/merchant-profile/55221', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bondi Body Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/55221', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/55221', 'affiliate_network', 'affiliate_program', 'Bondi Body''s own Awin merchant profile presents its at-home IPL beauty devices for partners: high-converting product, £190 average order value, creative assets and dedicated affiliate support, and names its affiliate manager contact: katherine@profectmarketing.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/55221', 'affiliate_network', 'commission_rate', 'The Awin profile states ''Competitive 4% commission on all sales (new + existing customers)'' and a ''30-day cookie window'', so 4% is recorded as the rate. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 13, 9, 4, '{"compensation": "4% is a low rate, partly offset by a \u00a3190 average order value; no cap statement is published, so the cap is honestly unknown.", "contact_access": "A named affiliate manager email is published on the brand''s own Awin profile, plus the network application.", "credibility": "Operating beauty-device brand with national press recognition (Good Housekeeping Institute, British Vogue) for its V2 device.", "niche_fit": "At-home IPL treatment journeys and results are demonstrable, series-friendly beauty UGC.", "opportunity_availability": "Open application through Awin, subject to network approval.", "ugc_evidence": "A partner-focused Awin profile with creative assets and dedicated support; no creator-specific program page or counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pistaché Skincare', 'https://pistacheskincare.com', 'Pistachio-based skincare brand (body oils, creams and serums built around pistachio oil). Its own Refersion affiliate portal publishes a lifetime tiered commission on referred sales — 10% up to $10,000, 15% from $10,001–$20,000 and 20% beyond $20,000 — with a 30-day cookie and PayPal payouts on the 15th of each month for commissions older than 30 days. The 10% starting tier is recorded as the rate. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pistacheskincare.refersion.com/.', 'https://pistacheskincare.refersion.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pistaché Skincare Affiliate Program (Refersion)', 'https://pistacheskincare.refersion.com/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pistacheskincare.refersion.com/', 'brand_site', 'affiliate_program', 'Pistaché Skincare''s own Refersion affiliate portal publishes its program agreement: affiliates earn tiered commission on the lifetime of referred sales — Tier 1 10% up to $10,000, Tier 2 15% from $10,001 to $20,000, and a Top Tier of 20% beyond $20,000. The 10% starting tier is recorded as the rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pistacheskincare.refersion.com/', 'brand_site', 'commission_rate', 'The brand''s own portal agreement also publishes a 30-day cookie and PayPal payment on the 15th of each month for commissions older than 30 days. The portal''s program-manager email renders masked, so no contact is recorded. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 14, 5, 9, 4, '{"compensation": "A published tier ladder from 10% to 20% on lifetime referred sales is attractive; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published \u2014 the portal''s manager email renders masked \u2014 so contact runs through the Refersion sign-up.", "credibility": "Operating DTC skincare brand with a full published affiliate agreement on its own portal.", "niche_fit": "A single-ingredient hero story (pistachio oil) gives skincare creators a clear routine and review angle.", "opportunity_availability": "Open self-serve sign-up on the brand''s Refersion portal.", "ugc_evidence": "A structured own-portal affiliate program with lifetime attribution; no creator-specific perks or counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Function of Beauty', 'https://www.functionofbeauty.com', 'Personalized haircare and skincare brand (custom shampoo, conditioner and serums formulated per customer). Its affiliate program is documented by multiple directories as paying a flat $25 per sale — Lasso and Influencer Marketing Hub agree on the flat figure, with a 7-day cookie and a $50 payout threshold reported — while one older roundup quotes 5%, so the flat bounty is recorded as flat and commission_rate stays null. ReferralCandy describes the program as paying ''dynamic commissions'' to individuals and publishers; no source names the hosting network. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (network not named in published sources)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/function-beauty/.', 'https://getlasso.co/affiliate/function-beauty/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Function of Beauty Affiliate Program', 'https://getlasso.co/affiliate/function-beauty/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/function-beauty/', 'affiliate_directory', 'commission_rate', 'Lasso''s program listing records Function of Beauty at a flat $25 per sale with a $50 payout threshold. A flat bounty is recorded as flat here, not as a percentage rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://influencermarketinghub.com/beauty-affiliate-programs/', 'affiliate_directory', 'commission_rate', 'Influencer Marketing Hub''s beauty affiliate roundup independently records Function of Beauty at $25 per sale with a 7-day cookie, agreeing with Lasso''s flat figure. One older roundup (Cloud Income) instead quotes 5% with a 10-day cookie, and ReferralCandy describes ''dynamic commissions'' without naming a network — so the flat $25 is the best-supported figure, commission_rate stays null, and the network is honestly unsettled. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 13, 5, 7, 5, '{"compensation": "A flat $25 per sale agreed by two directories is a solid bounty on personalized products, though one older 5% listing conflicts; cap unknown.", "contact_access": "No public program email is published; access runs through the program sign-up route.", "credibility": "Large, well-known personalized-beauty brand with national retail presence.", "niche_fit": "Custom-formula haircare is built for quiz-journey and routine UGC content.", "opportunity_availability": "Listed as joinable by individuals and publishers; the hosting network is not named in published sources.", "ugc_evidence": "Directories describe a partner program with exclusive promotions, banners and early launch access for affiliates."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mielle Organics', 'https://mielleorganics.com', 'Textured-hair care brand founded in 2014 by Monique Rodriguez and now a P&G Beauty subsidiary, known for its Rosemary Mint scalp oil. Its creator program is verified live by independent measurement: UGC Agent attributes 50 creator accounts to the program (4 confirmed, 46 likely) posting under #miellepartner, with a 5.1K median follower count — an absolute count on the ~100 scale, so creator_saturation is recorded as low with the confirmed/likely caveat stated in the evidence. The brand publishes no pay figure and no public join route was found in the sources reviewed, so commission_rate is null.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Mielle creator program; join route not published in sources reviewed)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://ugcagent.app/ugc-brands/mielle/.', 'https://mielleorganics.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mielle Organics Creator Program', 'https://mielleorganics.com', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ugcagent.app/ugc-brands/mielle/', 'third_party_measurement', 'ugc_program', 'UGC Agent''s measured record (sampled 28 October 2026) attributes 50 TikTok and Instagram accounts to Mielle''s UGC program — 4 confirmed and 46 likely — from a sample of 32 TikTok videos and 23 Instagram posts; all 50 counted accounts used the program hashtag #miellepartner, the median creator has 5.1K followers, 52% have under 10,000, and all sampled posts fall within the 90 days before sampling, so the program is live. The absolute count (~50 accounts) sits on the ~100 scale, so creator_saturation is recorded as low — transparently, most attributed accounts are ''likely'' rather than confirmed, and the sample is not a census.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ugcagent.app/ugc-brands/mielle/', 'third_party_measurement', 'commission_rate', 'UGC Agent states explicitly that Mielle has no published pay figure for its affiliate program that it could source — no rate card and no verifiable public report — and Lasso''s ''up to 6%'' figure is a ceiling, not a base rate. No public application or join route for the program was found in the sources reviewed. commission_rate is therefore recorded as null, and no source publishes an earnings cap statement, so commission_cap stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 5, 5, 5, 5, '{"compensation": "No pay figure is published anywhere sourced \u2014 only an ''up to 6%'' ceiling in one directory \u2014 so the rate is null and compensation scored at the floor; cap unknown.", "contact_access": "No public program email or application page was found in the sources reviewed; outreach runs through the brand''s site.", "credibility": "One of the fastest-growing multicultural hair brands, founded 2014, now a P&G Beauty subsidiary with national retail distribution.", "niche_fit": "Textured-hair routines and scalp-care content are core beauty UGC, and the program''s median creator is nano-sized (5.1K followers).", "opportunity_availability": "The program is verifiably live but publishes no join route, so availability is scored low despite the low saturation.", "ugc_evidence": "Independently measured: 50 attributed creator accounts, 55 sampled brand posts in 90 days, a unifying program hashtag and majority nano creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('OneSkin', 'https://www.oneskin.co', 'Longevity skincare brand built on the proprietary OS-01 peptide (face moisturizers, eye and lip products sold at premium prices). A structured program table lists OneSkin on Impact at 5%, while a Shopper program page quotes a generic ''up to 5-10%'' range that it prints for many brands — so the single-table 5% cannot be separated from the boilerplate range and commission_rate is recorded as null. Creators demonstrably promote the brand with affiliate links and codes. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://compareepc.com/skincare-affiliate-programs/.', 'https://compareepc.com/skincare-affiliate-programs/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'OneSkin Affiliate Program (Impact)', 'https://compareepc.com/skincare-affiliate-programs/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/skincare-affiliate-programs/', 'affiliate_directory', 'affiliate_program', 'CompareEPC''s skincare affiliate program table lists OneSkin on the Impact network at 5% commission (EPC $1.35). A Shopper program page instead quotes ''up to 5-10%'' — a generic range that page prints for many unrelated brands, so it cannot settle the rate against the single-table 5%.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://admin.shopper.com/partnerships/oneskin-co-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s One Skin US program page describes a partnership program paying commission on referred sales with instant approval through its platform, quoting the 5-10% range. Creator reviews of the brand carry affiliate links and personal discount codes (e.g. shrsl.com links), confirming creators actively promote it. Because the two published figures do not settle on one rate, commission_rate is recorded as null. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 8, 5, 8, 5, '{"compensation": "Published figures conflict between a single-table 5% and a boilerplate ''up to 5-10%'' range, so the rate is null and compensation scored cautiously; cap unknown.", "contact_access": "No public program email is published; access runs through the Impact application.", "credibility": "Established longevity-science skincare brand with published clinical studies and premium pricing.", "niche_fit": "Peptide longevity skincare is premium, education-led content that suits long-form review UGC.", "opportunity_availability": "Listed as an open program on Impact with instant-approval routes described by program pages.", "ugc_evidence": "Creator reviews carry affiliate links and personal discount codes, showing an active creator channel, though the brand publishes no creator program page of its own in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Billie', 'https://mybillie.com', 'Female-first shaving and body-care brand (razors, body wash, deodorant) owned by Edgewell. A directory listing records its affiliate program on Impact at 5% per sale, open to all regions; the listing was last updated in March 2024, so the figure is publicly_reported and dated. No earnings cap statement is published, so the cap stays unknown. (The brand''s separate friend-referral credits are a customer scheme and are not the recorded route.)', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/billie/.', 'https://linkclicky.com/affiliate-program/billie/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Billie Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/billie/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/billie/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s Billie listing records the female-first shaving and body brand''s affiliate program on the Impact platform at 5% commission per sale, all regions, with mybillie.com as the brand website. The listing was last updated March 10, 2024, so the terms are dated and flagged as such. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 9, 5, 7, 5, '{"compensation": "5% per sale is modest and rests on a single directory listing last updated in March 2024; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published; access runs through the Impact application.", "credibility": "Well-known national body-care brand owned by Edgewell Personal Care with mass retail distribution.", "niche_fit": "Everyday shaving and body-care routines are steady, relatable beauty UGC material.", "opportunity_availability": "Listed as open on Impact to all regions, subject to network approval.", "ugc_evidence": "A standard network affiliate listing; no creator-specific program page or measured creator counts are published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SideShaper', 'https://sideshaper.com', 'Home fitness brand built around the SideShaper low-impact ''reverse crunch'' core machine ($229-$299). Its own Collaborate page recruits influencers, bloggers, YouTubers and TikTok creators into a ShareASale-run affiliate program paying 20% per referral, with a 20% audience discount, a dedicated affiliate manager, and an ''Unlimited income potential'' statement on the brand''s own page - a verified-uncapped program.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://sideshaper.com/pages/collaborate.', 'https://sideshaper.com/pages/collaborate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SideShaper Affiliate Program (ShareASale)', 'https://sideshaper.com/pages/collaborate', 'https://sideshaper.com/pages/collaborate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sideshaper.com/pages/collaborate', 'official_program_page', 'commission_cap', 'The brand''s own Collaborate page, under ''Why partner with us?'': ''Unlimited income potential: We don''t set caps on the number of referrals, so the more you promote your custom link, the more you can earn.'' The heading explicitly states income potential is unlimited, so commission_cap is recorded as uncapped, documented transparently: the sentence ties the unlimited potential to there being no cap on referrals.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sideshaper.com/pages/collaborate', 'official_program_page', 'commission_rate', 'The same page: ''Earn 20% commissions per referral'' and ''Earn 20% per referral. Our product sells for $229 - $299, so you''ll earn an average of $52 for every sale.'' The audience receives a 20% discount, assets and UGC are provided, the program managers are named (Aimee and Rakesh), and tracking/payouts run through ShareASale.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sideshaper.com/pages/collaborate', 'official_program_page', 'creator_program', 'The page states the program ''is designed for high performing, value-driven platforms including influencers, bloggers, YouTubers, TikTok creators, and online businesses'' - an explicitly creator-facing program, not a trade scheme.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 16, 17, 8, 8, 3, '{"compensation": "20% per referral on a $229-$299 product (about $52 average per sale) with an explicit ''Unlimited income potential'' statement on the brand''s own page - verified uncapped.", "contact_access": "Two program managers are named on the page (Aimee and Rakesh), but no direct email is published, so access runs through the ShareASale sign-up.", "credibility": "An established single-product fitness brand with a detailed, current program page and named managers, though far smaller than the major equipment names.", "niche_fit": "A single demonstrable home-workout machine is ideal short-form fitness content - five-minute routines, before/after core work and low-impact training for home audiences.", "opportunity_availability": "Open application through the brand''s Collaborate page into ShareASale; no follower minimum is published.", "ugc_evidence": "The brand''s own page recruits influencers, bloggers, YouTubers and TikTok creators by name and supplies professionally designed assets plus user-generated content to promote with."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('REI', 'https://www.rei.com', 'REI Co-op, the member-owned outdoor retailer founded in 1938, sells camping, hiking, cycling, travel and outdoor apparel gear. Its affiliate program runs through AvantLink at a 5% per-sale commission reported consistently across the network''s own listings and program profiles, with application review for content sites and social channels focused on outdoor recreation.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/rei-co-op/.', 'https://getlasso.co/affiliate/rei-co-op/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'REI Affiliate Program (AvantLink)', 'https://getlasso.co/affiliate/rei-co-op/', 'https://getlasso.co/affiliate/rei-co-op/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/rei-co-op/', 'affiliate_network_profile', 'affiliate_program', 'Lasso''s Rei Co-op program profile, fetched directly: ''Commission Rate: 5% Per Sale'', 30-day cookie, $50 payout threshold, and the profile''s join link routes to AvantLink - matching the 5% AvantLink consensus across outdoor affiliate directories (Niche Pursuits, LinkWhisper and Afftank all report 5% via AvantLink).', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/rei-affiliate-program-in-depth-review-pros-and-cons', 'affiliate_directory', 'affiliate_program', 'Creator Hero''s in-depth review likewise reports the program is managed through AvantLink at up to 5% commission with a 15-day cookie in its table (cookie length varies by listing - 15 vs 30 days - so no cookie figure is recorded as settled). Approval requires an active site or social channel with original outdoor content; coupon-only sites are not accepted.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 13, 8, 5, 7, 5, '{"compensation": "5% per sale is modest, partly offset by high average order values on premium gear (about $120 AOV reported); no published cap statement was found, so the cap stays unknown.", "contact_access": "No public partnerships email was found on a fetched source; contact runs through the AvantLink advertiser relationship only.", "credibility": "A member-owned co-op operating since 1938 with tens of millions of members - as established as an outdoor retailer gets.", "niche_fit": "The broadest outdoor and travel-gear catalog in the directory - tents, packs, boots, apparel and travel gear give outdoor, hiking and travel creators endless review and list content.", "opportunity_availability": "Open to apply on AvantLink, but approval is reviewed case by case and coupon/deal-aggregation sites are excluded.", "ugc_evidence": "A long-running publisher program on AvantLink that accepts content sites and social channels with original outdoor content, though it is publisher-led rather than a creator-first ambassador scheme."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Viakix', 'https://www.viakix.com', 'New England-inspired outdoor footwear brand founded in 2015, making walking shoes and sandals for outdoor and travel use. Its own affiliate page publishes a 13% commission on every referred sale, a 60-day cookie, and an AvantLink application, and names bloggers, review sites and influencers across Instagram, YouTube and Facebook as its ideal partners; a dedicated affiliate contact email is published on the page.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliateprogram@viakix.com', null, 'https://www.viakix.com/pages/affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 13, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.viakix.com/pages/affiliate-program.', 'https://www.viakix.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Viakix Affiliate Program (AvantLink)', 'https://www.viakix.com/pages/affiliate-program', 'https://www.viakix.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.viakix.com/pages/affiliate-program', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''13% commission for every sale you refer'', a 60-day cookie duration, free US shipping and returns, and ''We''ve partnered with AvantLink'' with the application button routing to AvantLink.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.viakix.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'The same page: ''Our ideal partners will be content producers such as bloggers, review sites, and influencers across Instagram, YouTube, Facebook, and other social media platforms'', and it publishes the contact affiliateprogram@viakix.com for program questions. No cap statement appears on the page, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 14, 12, 8, 3, '{"compensation": "13% on every referred sale with a 60-day cookie is above the outdoor-footwear norm; no published cap statement was found, so the cap is honestly unknown.", "contact_access": "A dedicated affiliate email (affiliateprogram@viakix.com) is published on the program page itself - direct access most brands in this round do not offer.", "credibility": "Operating since 2015 with a real storefront and a documented give-back program, but a small single-category brand rather than a household name.", "niche_fit": "Comfort walking and outdoor footwear is natural travel, hiking and everyday-adventure content - fit tests, walking tours and travel packing videos.", "opportunity_availability": "Open application from the brand''s own page into AvantLink, free to join.", "ugc_evidence": "The brand''s own page explicitly recruits bloggers, review sites and influencers across Instagram, YouTube and Facebook, with customizable marketing materials offered to partners."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Beckett Simonon', 'https://www.beckettsimonon.com', 'Made-to-order men''s leather shoes, boots and accessories, handcrafted in the brand''s own Bogota studio and sold direct-to-consumer in the US. The brand''s own help center confirms an affiliate program paying 20% commission on first orders from new customers referred, run through Refersion, with free samples, pre-release notifications and training for affiliates.', 'Colombia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'info@beckettsimonon.com', null, 'https://www.beckettsimonon.com/apps/help-center?srsltid=AYCX9vJW1nalYhj8c-klEpkqjzrJf7HqM78nmEp_8XyBXugEy0s96DVs#!hc-how-can-i-track-my-order', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.beckettsimonon.com/apps/help-center?srsltid=AYCX9vJW1nalYhj8c-klEpkqjzrJf7HqM78nmEp_8XyBXugEy0s96DVs#!hc-how-can-i-track-my-order.', 'https://beckettsimonon.refersion.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Beckett Simonon Affiliate Program (Refersion)', 'https://beckettsimonon.refersion.com', 'https://www.beckettsimonon.com/apps/help-center?srsltid=AYCX9vJW1nalYhj8c-klEpkqjzrJf7HqM78nmEp_8XyBXugEy0s96DVs#!hc-how-can-i-track-my-order', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.beckettsimonon.com/apps/help-center?srsltid=AYCX9vJW1nalYhj8c-klEpkqjzrJf7HqM78nmEp_8XyBXugEy0s96DVs#!hc-how-can-i-track-my-order', 'brand_site', 'commission_rate', 'The brand''s own help center FAQ, fetched directly: ''Do you have an Affiliate program? Yes, we do. As a Beckett Simonon Affiliate, you will receive a 20% commission on first orders from new customers you refer to us. Affiliates also get great perks such as free samples, pre-release notification of new products, training, tips, text, images...'' - the apply link routes to beckettsimonon.refersion.com. The 20% is recorded with its basis: first orders from new customers only.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/beckett-simonon/', 'affiliate_directory', 'affiliate_program', 'Lasso''s program profile agrees on 20% per sale with a 30-day cookie, and The Affiliate Monkey''s review confirms the program is hosted on Refersion with commissions processed net 30 via PayPal. Shopper''s generic 5-10% Sovrn payout figure is a different resale route and was not credited as the program rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 17, 9, 7, 4, '{"compensation": "20% commission is at the top of men''s fashion - with the honest limit that it applies to first orders from new customers only, per the brand''s own FAQ. No cap statement was found.", "contact_access": "Applications run through the brand''s Refersion portal and its help center publishes a business-inquiry email (info@beckettsimonon.com), with an Affiliates Liaison named as the follow-up contact.", "credibility": "An established direct-to-consumer maker with its own workshop, thousands of five-star reviews per its help center, and a one-year warranty.", "niche_fit": "Handcrafted leather shoes and boots are core men''s style content - craftsmanship stories, made-to-order explainers, styling and long-term wear reviews.", "opportunity_availability": "Open application on Refersion; approval is by the brand''s Affiliates Liaison rather than instant.", "ugc_evidence": "The brand''s own FAQ confirms a working affiliate scheme with free samples, pre-release access and creative support for affiliates, though it is not a social-first ambassador program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kizik', 'https://kizik.com', 'Hands-free slip-on footwear brand - shoes you step into without tying laces or crushing the heel. Its affiliate program runs on Impact; published rate figures conflict between directories (5% vs 10%), so no rate is recorded as settled, but the program''s existence and network are consistent across sources.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/kizik/.', 'https://linkclicky.com/affiliate-program/kizik/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kizik Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/kizik/', 'https://linkclicky.com/affiliate-program/kizik/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/kizik/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s program listing: Kizik''s affiliate platform is Impact and the commission is 5% per sale.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/kizik', 'affiliate_directory', 'commission_rate_conflict', 'InfluencerRate''s review instead reports a flat 10% per sale via Impact Radius with monthly PayPal payouts. Because the two fetched directories conflict (5% vs 10%) and no brand or network page fetched settles the figure, commission_rate is recorded as null with the conflict documented here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 5, 7, 4, '{"compensation": "Unscored generously because the rate could not be settled: fetched directories report 5% (LinkClicky) and 10% (InfluencerRate) on the same Impact program, so the rate is null and the cap unknown.", "contact_access": "No public partnerships email was found on a fetched source; access is through Impact only.", "credibility": "A well-known, heavily marketed footwear innovator with national retail presence - a real brand, with only its affiliate rate left unsettled.", "niche_fit": "Step-in hands-free shoes are made for short-form video - the step-in demo is a natural hook for footwear, parenting, travel and accessibility content.", "opportunity_availability": "Open application via Impact with reported fast approval.", "ugc_evidence": "A standard Impact publisher program rather than a creator-first scheme; directories describe approval in 24-48 hours and link generation through the Impact dashboard."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KEEN Footwear', 'https://www.keenfootwear.com', 'Outdoor and everyday footwear brand known for its wide toe-box hiking boots, sandals and shoes. Its US affiliate program runs through CJ Affiliate at 6% per sale with a 30-day cookie, per the fetched Lasso program profile whose join link routes to CJ signup; a separate UK programme exists on Awin.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/keen-footwear/.', 'https://getlasso.co/affiliate/keen-footwear/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'KEEN Footwear Affiliate Program (CJ Affiliate)', 'https://getlasso.co/affiliate/keen-footwear/', 'https://getlasso.co/affiliate/keen-footwear/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/keen-footwear/', 'affiliate_network_profile', 'affiliate_program', 'Lasso''s KEEN Footwear profile, fetched directly: ''Commission Rate: 6% Per Sale'', 30-day cookie, categories Fashion and Shoes, and the profile''s join buttons route to signup.cj.com - the CJ Affiliate network. A second Lasso profile (KEEN Footwear US) reports the same 6% and 30 days.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/123960', 'affiliate_network_profile', 'affiliate_program', 'Awin''s own merchant profile hosts a separate KEEN Footwear UK affiliate programme (30-day cookie), confirming KEEN runs network affiliate programs in more than one region. Shopper''s generic 5-10% range brackets the settled 6% US figure rather than conflicting with it; no cap statement was found in any fetched source.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 5, 7, 5, '{"compensation": "6% per sale with a 30-day cookie is mid-pack for footwear; no published cap statement was found, so the cap stays unknown.", "contact_access": "No public partnerships email was found on a fetched source; contact runs through the CJ advertiser relationship.", "credibility": "One of the largest independent US footwear brands, sold worldwide for over two decades.", "niche_fit": "Hiking boots, sandals and everyday shoes span outdoor, travel and casual-fashion content - trail reviews, comfort tests and family footwear roundups.", "opportunity_availability": "Open application through CJ Affiliate with the usual network review.", "ugc_evidence": "A standard network publisher program on CJ (with an Awin UK counterpart) aimed at bloggers and influencers per the fetched profile, not a bespoke creator scheme."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Far & Wild', 'https://www.farandwild.com', 'US outdoor retailer (Far & Wild LLC) selling premium outdoor clothing and gear brands for hiking, camping and travel. Its affiliate program runs on Refersion under published terms: 10% of product revenue (excluding tax and shipping), paid monthly by PayPal once earnings pass $100, open to US-based affiliates.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://farandwild.refersion.com/.', 'https://farandwild.refersion.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Far & Wild Affiliate Program (Refersion)', 'https://farandwild.refersion.com/', 'https://farandwild.refersion.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://farandwild.refersion.com/', 'official_program_terms', 'commission_rate', 'The program''s own Refersion terms of service, fetched directly: ''Commissions are 10% of product revenue which does not include sales tax and shipping charges. Commissions are paid every month.'' Payments are by PayPal only and begin once an affiliate has earned more than $100; affiliates must live in the United States. The 10% is recorded with its basis: product revenue excluding tax and shipping.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://farandwild.refersion.com/', 'official_program_terms', 'affiliate_program', 'The same terms describe a standard creator/publisher setup - unique affiliate codes, banners and graphics provided in a shared folder, and special tracked links - with no cap on earnings stated anywhere in the terms, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 13, 5, 7, 3, '{"compensation": "10% of product revenue (excluding tax and shipping) paid monthly via PayPal is solid for outdoor retail; the $100 payout threshold and the absence of any cap statement keep it mid-scored.", "contact_access": "No public partnerships email appears in the fetched terms; contact runs through the Refersion program only.", "credibility": "A real operating outdoor retailer with full published program terms, though much smaller and less known than the national outdoor chains.", "niche_fit": "A curated premium outdoor catalog gives hiking, camping and travel creators branded gear to review without needing a single-brand wardrobe.", "opportunity_availability": "Open sign-up on Refersion, but restricted to affiliates living in the United States per the program''s own terms.", "ugc_evidence": "The published terms are publisher-style (links, banners, codes) rather than a creator-first ambassador program, so UGC evidence is thinner than the brand-direct schemes in this batch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CARIUMA', 'https://int.cariuma.com', 'Brazilian sustainable sneaker brand making canvas and knit shoes from bamboo, organic cotton and other low-impact materials, with a tree-planting program in the Brazilian rainforest. It runs an affiliate program through Rakuten Advertising, but published rate figures conflict sharply across fetched sources (5% vs 32% vs a 5-10% range), so no rate is recorded as settled.', 'Brazil', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/cariuma/.', 'https://linkclicky.com/affiliate-program/cariuma/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CARIUMA Affiliate Program (Rakuten Advertising)', 'https://linkclicky.com/affiliate-program/cariuma/', 'https://linkclicky.com/affiliate-program/cariuma/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cariuma/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s listing: CARIUMA''s affiliate platform is Rakuten Advertising and the commission is 5% per sale (listing scoped to the AU region).', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/cariuma/', 'affiliate_directory', 'commission_rate_conflict', 'Lasso''s profile instead claims 32% per sale with a 30-day cookie, and Shopper reports a 5-10% payout range. A 32% headline cannot be reconciled with the 5% Rakuten listing, and no brand or network page fetched settles the figure, so commission_rate is recorded as null with the conflict documented here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 7, 5, 6, 4, '{"compensation": "Scored low because the rate is unsettleable from fetched sources: 5% (LinkClicky/Rakuten) against 32% (Lasso) and 5-10% (Shopper) - rate null, cap unknown.", "contact_access": "No public partnerships email was found on a fetched source; access is through Rakuten Advertising only.", "credibility": "A genuine, well-known sustainable footwear brand with global distribution - only its affiliate economics are unclear.", "niche_fit": "Sustainable sneakers are strong fashion and conscious-living content - styling, materials stories and skate/streetwear crossovers.", "opportunity_availability": "Listed as open to apply via Rakuten, with the fetched listing scoped to the AU region, which narrows availability.", "ugc_evidence": "A network publisher program via Rakuten rather than a creator-first scheme; directories describe a standard application and dashboard flow."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tommy John', 'https://www.tommyjohn.com', 'Comfort-focused underwear, loungewear and basics brand for men and women, built on stay-put waistbands and performance fabrics. Its affiliate program runs on Impact; the only fetched program listing publishes a 4%-8% per-sale range rather than a single rate, so no single rate is recorded as settled.', 'United States', 'published') returning id into bid;
