  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/tommy-john/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s program listing: Tommy John''s affiliate platform is Impact, open in all regions, with commission published as a 4%-8% per-sale range. Because the fetched source publishes a range rather than one rate, commission_rate is recorded as null with the range documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopday.com/tommy-john', 'affiliate_directory', 'affiliate_program', 'Shopday''s listing confirms the program exists and is free to join but publishes no rate (''varies by partner''), so it does not settle the figure. No cap statement was found in any fetched source, so commission_cap stays unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 5, 7, 5, '{"compensation": "The published 4%-8% range is modest for apparel and could not be narrowed to one settled rate from fetched sources, so the rate is null and the cap unknown.", "contact_access": "No public partnerships email was found on a fetched source; contact runs through Impact only.", "credibility": "A long-established, nationally retailed basics brand - credibility is not the issue; only its exact affiliate rate is unpublished as a single figure.", "niche_fit": "Underwear, loungewear and basics are everyday-essentials content - comfort tests, travel packing and workday basics for men''s and women''s fashion creators.", "opportunity_availability": "Open application via Impact, listed for all regions.", "ugc_evidence": "A standard Impact publisher program; the fetched listings describe open application and link tools rather than a creator-first ambassador scheme."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nobis', 'https://inc.nobis.com', 'Canadian luxury performance outerwear brand founded in 2009, making premium parkas, jackets and technical apparel. Its own affiliate page launches the ''Nobis Navigator'' program for creators, publishers and tastemakers, offering commissions on qualifying sales plus creative resources and reporting tools - but the page publishes no commission rate, so none is recorded.', 'Canada', 'published') returning id into bid;
