  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://inc.nobis.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'The brand''s own affiliate page, fetched directly: ''Become a Nobis Navigator. Join a global community of creators, publishers, and tastemakers...'' and ''Our affiliate program invites like-minded partners to share our collections with their audiences and earn commissions on qualifying purchases'', with product imagery, campaign assets, banners and affiliate reporting tools listed as benefits.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://inc.nobis.com/pages/affiliate-program', 'official_program_page', 'commission_rate', 'The same page promises only ''competitive commissions on qualifying sales generated through your unique affiliate links'' - no percentage or cap statement is published anywhere on the fetched page, so commission_rate is null and commission_cap is unknown rather than guessed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 7, 6, 7, 4, '{"compensation": "Scored low on evidence, not on promise: the page says ''competitive commissions'' but publishes no rate and no cap statement, so both stay honestly unsettled.", "contact_access": "The program is presented on the brand''s own site with a partnership pitch (''Connect with the Nobis team''), but no direct email was published on the fetched page.", "credibility": "A genuine luxury outerwear label founded in Canada in 2009 and sold internationally - established, with only its affiliate economics unpublished.", "niche_fit": "Luxury parkas and technical outerwear are premium fashion and winter-travel content - cold-weather tests, city styling and high-end gear reviews.", "opportunity_availability": "Open partner invitation on the brand''s own affiliate page; no follower minimum is published.", "ugc_evidence": "The brand''s own page is explicitly creator-facing - it recruits creators, publishers and tastemakers by name and offers campaign assets and reporting tools."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Enviromedica', 'https://enviromedica.com', 'Enviromedica is a US wellness brand behind the Ancient Minerals magnesium line and other ancestral-health products, and it runs an affiliate program through Refersion aimed at wellness, body-care and ancestral-health content creators.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://enviromedica.com/pages/affiliate-program.', 'https://enviromedica.refersion.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Enviromedica Affiliate Program', 'https://enviromedica.refersion.com', 'https://enviromedica.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://enviromedica.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'Enviromedica''s own affiliate page, fetched first-hand, invites wellness, body-care and ancestral-health creators to apply and publishes recurring commission on qualifying sales, a 30-day cookie window, real-time reporting and free joining, with applications managed through the brand''s Refersion portal. The only rate wording on the page is ''Receive up to 15% commission per sale'' — an up-to ceiling, not a published flat rate — so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 10, 7, 9, 4, '{"compensation": "Recurring commission is confirmed, but the only published figure is an ''up to 15%'' ceiling, so no flat rate can be recorded.", "contact_access": "Application runs through the brand''s Refersion portal; no public partnerships email was published on the fetched page.", "credibility": "An established US wellness brand with a long-running flagship product line (Ancient Minerals).", "niche_fit": "Magnesium, body-care and ancestral-health products are everyday, demonstrable staples for wellness and routine creators.", "opportunity_availability": "Program is live and free to apply now from the brand page.", "ugc_evidence": "The brand''s own page explicitly recruits affiliates with a trusted voice and a genuine audience connection, and reviews each application for fit."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zivolife', 'https://zivo.life', 'Zivolife sells a single whole-food microalgae nutrition product built on ZL01, its patented Klebsormidium flaccidum strain, at $99 one-time or $69 on subscription, and has just opened a brand-new affiliate program through GoAffPro with a dedicated track for content creators and influencers.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://zivo.life/pages/zivolife-partners.', 'https://zivo-life.goaffpro.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zivolife Affiliate Program', 'https://zivo-life.goaffpro.com', 'https://zivo.life/pages/zivolife-partners', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zivo.life/pages/zivolife-partners', 'brand_website', 'affiliate_program', 'Zivolife''s own partners page, fetched first-hand, headlines ''New Affiliate Program — Now Open'' and ''First In Wins — Ground Floor'', and runs a dedicated Content Creators & Influencers track (YouTube, Instagram and TikTok creators, bloggers, podcasters) applying through GoAffPro with review inside 48 hours. The program pays a first-order percentage plus recurring commission on subscription renewals, but the full rate, cookie window and payout schedule are shared only with approved affiliates, so commission_rate is null and commission_cap is unknown. creator_saturation is low on brand-new-program evidence: the program has only just opened, per the brand''s own page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 9, 7, 10, 3, '{"compensation": "Recurring subscription commission is confirmed, but no rate is published before approval, so no rate can be recorded.", "contact_access": "Application runs through the brand''s GoAffPro portal with a stated 48-hour review; no public partnerships email was published.", "credibility": "A new, single-product brand; it cites human RCTs and third-party verification, but has little track record yet.", "niche_fit": "A single, novel, science-led nutrition product gives health and wellness creators a story no competing product can tell.", "opportunity_availability": "The program has just opened and is actively recruiting its first affiliates now.", "ugc_evidence": "A dedicated creator/influencer track, a creative library with product photography and social assets, and compliance-approved messaging are all published on the brand''s own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Enzymedica', 'https://enzymedica.com', 'Enzymedica is a long-running US digestive-health brand — maker of Digest Gold and positioned as the #1 digestive enzyme brand in the U.S. — that runs a brand-direct affiliate program for customers and creators who share its products with their communities.', 'United States', 'published') returning id into bid;
