  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Enzymedica Affiliate Program', 'https://enzymedica.com/pages/affiliate-program-2', 'https://enzymedica.com/pages/affiliate-program-2', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://enzymedica.com/pages/affiliate-program-2', 'brand_website', 'affiliate_program', 'Enzymedica''s own affiliate page, fetched first-hand, confirms the program: affiliates earn a commission and give followers an exclusive discount, and joining starts by filling out the brand''s contact form and selecting Marketing. The brand''s own page publishes no commission rate; a Lasso directory listing reports 10% with a 45-day cookie, but a single third-party directory figure the brand itself does not publish is not recorded as the rate, so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 9, 5, 8, 5, '{"compensation": "Commission is confirmed but the brand publishes no rate; a single directory reports 10%, which is documented but not recorded.", "contact_access": "No application portal or partnerships email \u2014 joining starts from a general contact form (select Marketing).", "credibility": "One of the most established digestive-enzyme brands in the US, with over two decades in natural digestive health.", "niche_fit": "Digestive enzymes and gut-health products are a staple, highly searchable category for health and wellness creators.", "opportunity_availability": "Program is live and joinable now from the brand page.", "ugc_evidence": "A live brand-direct affiliate program with follower discounts, though the page speaks to customers more than to professional creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Organic Olivia', 'https://www.organicolivia.com', 'Organic Olivia is a US herbal wellness brand blending plant medicine, ancestral wisdom and modern science in tinctures and formulas, and runs an affiliate program through ShopMy that pays creators 15% on new sales they refer.', 'United States', 'published') returning id into bid;
