  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Organic Olivia Affiliate Program', 'https://www.organicolivia.com/pages/affiliate', 'https://www.organicolivia.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.organicolivia.com/pages/affiliate', 'brand_website', 'affiliate_program', 'Organic Olivia''s own affiliate page, fetched first-hand, publishes the full offer: earn 15% commission on every new sale referred through a unique link or code, share across Instagram, TikTok, YouTube and Substack, get paid on a regular schedule through ShopMy, with top performers unlocking bonus tiers, gifting and early access. The page also publishes a dedicated affiliate contact email, affiliates@organicolivia.com. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 15, 12, 9, 4, '{"compensation": "15% on every new sale, published on the brand''s own page; no cap statement, so the cap is unknown.", "contact_access": "A dedicated affiliates@ email is published on the program page, alongside the ShopMy sign-up route.", "credibility": "An established, founder-led herbal wellness brand with a loyal community.", "niche_fit": "Herbal tinctures and daily wellness rituals are natural, repeatable content for wellness creators.", "opportunity_availability": "Program is live and joinable now from the brand page.", "ugc_evidence": "The brand calls affiliates the heart of its mission, supports link and list building through ShopMy, and rewards top creators with gifting and early access."}'::jsonb);
