  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://humantonik.com/supergreen-tonik-affiliate-program/', 'brand_website', 'affiliate_program', 'Human Tonik''s own affiliate page, fetched first-hand, publishes the full structure: 30% commission on the first referral, lifetime commissions of 15%, a 365-day cookie duration and high average order values, with partner registration through the brand''s own associates portal. The 30% first-referral rate is recorded, with the 15% lifetime rate documented here. The product has been on the market for five years and is US-manufactured and third-party tested, per the same page. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
