  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/health-ade/', 'affiliate_directory', 'commission_rate_conflict', 'Health-Ade''s program route is settled but its rate is not: LinkClicky''s network listing (updated March 2024) records Health-Ade on the Impact network at 10% per sale, while Shopper''s partnership listing reports a 2.66% payout. Because the published figures conflict, commission_rate is null and the conflict is documented here; the Impact route itself is consistent. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
