  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://promix-nutrition.gorgias.help/en-US/how-does-the-referral-program-work-401532', 'brand_website', 'affiliate_program', 'Promix Nutrition''s own help center, fetched first-hand, states the brand is ''now partnering with Shopify Collabs on our new referral program'' and encourages applications, describing the program as ''made up of a community of talented content creators, fitness enthusiasts'' united by the brand. Published rates conflict — Lasso lists ''up to 15%'' (a ceiling) while Shopper reports 5–10% — so commission_rate is null and the conflict is documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
