  insert into public.brands (name, website, description, country, status) values ('SharkNinja', 'https://www.sharkninja.com', 'Global home-appliance company behind the Shark cleaning and Ninja kitchen brands, sold through sharkninja.com. Its own Storytellers creator program, launched in October 2026, invites consumers to post unboxings, how-tos and honest reviews and earn storefront commission starting at 8% and growing to 10%; it is free to join for US advocates with at least 1,000 total followers.', 'United States', 'published') returning id into bid;
