  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sharkninja.com/discover/community/storytellers', 'official_site', 'affiliate', 'SharkNinja''s own Storytellers page fetched in full: ''Join SharkNinja Storytellers for free'', creators post unboxings, how-tos and honest reviews, and ''Commissions start at 8% and grow to 10%'' on orders from the creator''s storefront, paid monthly after the return period closes. Requirements published on the page: at least 1,000 followers in total, posted in the last 30 days, US advocates only for now. The recorded 8% is the brand-published starting rate. No earnings-cap statement is published, so the cap is unknown, and no absolute creator count is published (the program launched in October 2026 per the company''s launch release), so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 14, 10, 8, 5, '{"compensation": "A brand-published starting rate of 8% growing to 10% on high-ticket appliances is solid, transparent pay; no cap statement is published", "contact_access": "Application runs through the brand''s own Storytellers page; no direct affiliate email is published", "credibility": "A large, publicly traded global appliance company with a terms-published creator program on its own site", "niche_fit": "Shark vacuums and Ninja kitchen appliances are among the most demonstrated products in home UGC \u2014 air-fryer recipes, cleaning tests and unboxings are core creator content", "opportunity_availability": "Free and open to US advocates meeting the published 1,000-follower minimum", "ugc_evidence": "A brand-run creator program built for consumers'' own content, with challenges, tiers, gifted products and a storefront \u2014 direct, explicit creator evidence on the brand''s own page"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SparkFun', 'https://www.sparkfun.com', 'Electronics retailer for makers, educators and engineers — development boards, sensors and DIY project components, including its own SparkFun Original product line — sold through sparkfun.com. Its own affiliate program pays 10% commission on eligible SparkFun Original products, is free to join, and pays out via PayPal with a $10 minimum.', 'United States', 'published') returning id into bid;
