  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sparkfun.com/affiliate-program', 'official_site', 'affiliate', 'SparkFun''s own affiliate program page fetched in full: affiliates earn ''10% commission on eligible SparkFun Original products'' purchased through their referral links (third-party manufacturer products are not eligible), the program is free to join, commissions are paid via PayPal with a $10 minimum payout, and the page explicitly addresses creators, educators, makers and engineers who showcase projects on websites, blogs, YouTube and social media. The recorded 10% is the brand''s own published figure. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 13, 10, 9, 4, '{"compensation": "A brand-published 10% is a fair rate, though it applies only to SparkFun Original products, not the whole catalogue; no cap statement is published", "contact_access": "Signup runs through a SparkFun account from the official program page; no direct affiliate email is published", "credibility": "A two-decade-old, well-known name in maker electronics with a complete terms-published program page", "niche_fit": "DIY electronics, robotics and maker projects are a thriving tutorial and build-video UGC niche, though narrower than mainstream consumer tech", "opportunity_availability": "Free to join from the brand''s own page, with a low $10 payout minimum", "ugc_evidence": "The brand''s own page explicitly recruits creators, educators and makers producing project and tutorial content \u2014 direct creator-facing program evidence"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('EarFun', 'https://www.myearfun.com', 'Wireless audio brand — earbuds and speakers with multiple Red Dot and CES Innovation awards — sold through myearfun.com. Its own affiliate page recruits review sites, bloggers, communities and social publishers, publishes the contact affiliate@myearfun.com, and displays Awin and Impact as its networks; published rates conflict, so no single rate is settled.', 'China', 'published') returning id into bid;
