  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.myearfun.com/earfun-affiliate', 'official_site', 'affiliate', 'EarFun''s own affiliate page fetched in full: it invites review sites, online communities, bloggers and social media publishers, advertises ''Earn up to 20% Commission'' (a ceiling, not a settled rate), a 30-day order validation window, and the published contact affiliate@myearfun.com; the page displays Awin and Impact logos as its program networks. The brand page publishes no single settled rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/61233?setLocale=nb_NO', 'listing', 'affiliate', 'Rate-conflict note: EarFun''s Awin profile states an 8%-15% commission range, Lasso reports 8% per sale, and Shopper reports 5-10%, while the brand''s own page advertises up to 20%. Because the published sources span 5% to a 20% ceiling without settling, commission_rate is null with the conflict documented here; the recorded network is Awin per the brand page''s own network display and its Awin profile. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
