  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Breville Affiliate Program — premium kitchen appliances via Impact at a reported 8% per sale (three listings agree; lower 3.96% and ~2.2% reports documented)', 'https://linkclicky.com/affiliate-program/breville/', 'https://linkclicky.com/affiliate-program/breville/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/breville/', 'listing', 'affiliate', 'LinkClicky''s Breville program listing fetched in full: affiliate platform Impact, commission ''8% per sale'', described as ''just what''s officially listed with their affiliate program'', with the join route leading to Breville''s application on app.impact.com. AdCompares independently reports Breville at up to 8% per sale on Impact with a 30-day cookie, and a HowToJoin guide also reports 8% — three sources agree on 8% via Impact, so 8% is recorded as publicly_reported.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/breville/', 'listing', 'affiliate', 'Conflict note: Shopper reports a 3.96% payout and LinkApprove estimates about 2.2% per sale on its own sample — both documented here rather than recorded; the three agreeing 8% reports, including one describing the figure as the officially listed Impact rate, govern. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 11, 12, 9, 8, 5, '{"compensation": "8% agreed by three independent listings on premium-priced appliances is fair pay, though two lower reports exist and are documented; no cap statement exists", "contact_access": "Application runs through the Impact join route on the program listing; no direct affiliate email is published", "credibility": "A category-defining premium appliance brand operating since 1932", "niche_fit": "Espresso machines and smart ovens are hero products of coffee and kitchen UGC \u2014 latte-art, unboxing and routine content are proven formats", "opportunity_availability": "Open application through Impact, subject to approval", "ugc_evidence": "A standing program on a major network with consistent reporting; it is publisher-oriented rather than a dedicated creator program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Keyport', 'https://www.mykeyport.com', 'Modular everyday-carry brand — Pivot and Slide key organizers, Anywhere Tools and Versa58 scales for 58mm Swiss Army knives — sold through mykeyport.com. Its own affiliate page states the program runs on Awin with a 7% standard commission, up to 12% for top partners, and a 30-day cookie.', 'United States', 'published') returning id into bid;
