  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mykeyport.com/pages/affiliate', 'official_site', 'affiliate', 'Keyport''s own affiliate page fetched in full: ''The Keyport affiliate program runs on Awin. Partners earn a 7% standard commission on referred sales, with rates up to 12% for top partners'', a 30-day cookie, Awin advertiser ID 88217, and every product line earning the same commission. The page recruits content creators, review sites, gift-guide publishers and YouTube channels in EDC, gadgets and tech, and states ShareASale closed in October 2025 with the program now on Awin. The recorded 7% is the brand''s own published standard rate. The page''s partner-support email is masked in the fetched text, so no email is recorded. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 12, 10, 9, 4, '{"compensation": "A brand-published 7% standard rate rising to 12% for top partners is transparent, mid-range pay; no cap statement is published", "contact_access": "Application via Awin from the brand''s own program page; the support email is masked in the published page text, so no email is recorded", "credibility": "Operating since 2005 with coverage in Forbes, Wired and CNET cited on its own program page, and complete published terms", "niche_fit": "EDC gear, key organizers and pocket-dump content are a dedicated gadget UGC niche \u2014 smaller than mainstream tech but highly engaged", "opportunity_availability": "Open application through Awin from the brand''s own page, subject to a fit review", "ugc_evidence": "A brand-published program that explicitly names content creators and YouTube channels as target partners; no separate creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Wisdom Panel', 'https://www.wisdompanel.com', 'Pet DNA testing brand within Mars Petcare — breed, trait and health screening tests for dogs and cats — sold through wisdompanel.com. Its own affiliate page recruits content creators (''Calling all pet lovers with a following''), and the program runs on Impact, where two independent listings agree on a 6% commission.', 'United States', 'published') returning id into bid;
