  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wisdompanel.com/en-us/affiliates-program', 'official_site', 'affiliate', 'Wisdom Panel''s own affiliate program page fetched: headed ''Calling all pet lovers with a following'', it invites vets who share tips online, pet parents, pet hotels, shelters and grooming salons, stating ''We''re open to creating relationships with all kinds of content creators.'' The brand page publishes no commission percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wisdompanel.com/en-us/affiliates-program', 'listing', 'affiliate', 'Rate reporting: LinkClicky lists Wisdom Panel on Impact at 6% per sale (''just what''s officially listed''), and Meer''s World independently reports the Wisdom Panel program on Impact Radius at 6% commission — two sources agree, so 6% is recorded as publicly_reported. Shopper instead reports 4.8%, and one 2026 comparison guide describes the rate as unpublished; both are documented here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
