  insert into public.brands (name, website, description, country, status) values ('BISSELL', 'https://www.bissell.com', 'Floorcare brand operating since 1876 — CrossWave multi-surface cleaners, SpotClean portable cleaners and pet-proven cleaning machines — sold through bissell.com. Its affiliate programme on Awin (the fetched UK programme profile) publishes a 3% base commission on validated sales with tiered rates up to 10%, a 30-day cookie and £150+ average order value.', 'United States', 'published') returning id into bid;
