  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 9, 11, 8, 5, '{"compensation": "A 3% base rate is low, though tiers reach 10% and bespoke content rates exist, on a \u00a3150+ average order; no cap statement exists", "contact_access": "Published account-team email (partner@deptagency.com, the programme''s agency team) on the Awin profile, plus the network application route", "credibility": "A global floorcare leader operating since 1876 \u2014 maximum credibility in this batch", "niche_fit": "Floorcare and pet-mess cleaning demos are a core home UGC category \u2014 before/after and stain-test content is natural and proven", "opportunity_availability": "Open application through Awin, subject to approval", "ugc_evidence": "A standing Awin programme whose profile offers bespoke higher rates to content publishers and bloggers; no dedicated creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vitamix', 'https://www.vitamix.com', 'High-performance blender brand — premium home blenders and accessories — sold through vitamix.com. Its own affiliates page confirms the program and its content-creator focus; the program is managed through CJ Affiliate, and published rate reports conflict widely, so no single rate is settled.', 'United States', 'published') returning id into bid;
