  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.vitamix.com/us/en_us/owners-resources/affiliates/.', 'https://www.vitamix.com/us/en_us/owners-resources/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vitamix Affiliate Program — premium blenders via CJ Affiliate (four sources agree on the network); published rates conflict (3% / 10% / 15% / up to 10%), so the rate is unsettled', 'https://www.vitamix.com/us/en_us/owners-resources/affiliates/', 'https://www.vitamix.com/us/en_us/owners-resources/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vitamix.com/us/en_us/owners-resources/affiliates/', 'official_site', 'affiliate', 'Vitamix''s own affiliates page fetched: ''The Vitamix Affiliate Program allows you to generate passive income while sharing your love of food, fitness, life hacks and more... you''ll earn commissions simply by including purchase links in the top-notch content you are already creating and sharing with your fans'', with early access to products and news through the affiliate portal. The brand page publishes NO commission percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vitamix.com/us/en_us/owners-resources/affiliates/', 'listing', 'affiliate', 'Network and rate-conflict note: HowToJoin, Uppromote, Post Affiliate Pro and a long-standing program guide all agree the program is managed through CJ Affiliate. Rate reports conflict widely — starting at 3% in an older guide, ''starts at 10% for content-creating affiliates'' per Uppromote, 15% per Lasso, and up to 10% per Shopper and Creator Hero — so commission_rate is null with the conflict documented here. One guide also reports a minimum of 6 machine sales per year to stay in the program. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 10, 9, 7, 5, '{"compensation": "Reports span 3% to 15% on $400+ machines without settling, so compensation is scored on unsettled evidence; no cap statement exists", "contact_access": "Application runs through CJ Affiliate from the brand''s own affiliates page; no direct affiliate email is published", "credibility": "The category-defining premium blender brand with a century of operating history", "niche_fit": "High-performance blending is a staple of recipe, smoothie and kitchen-upgrade UGC, with strong demo value on premium machines", "opportunity_availability": "Open application through CJ, though one guide reports a 6-machine annual sales minimum to remain in the program", "ugc_evidence": "The brand''s own affiliates page frames the program around creators sharing content with fans; no separate creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Misen', 'https://www.misen.com', 'Direct-to-consumer kitchenware brand — chef''s knives, stainless and carbon-nonstick cookware and kitchen tools — sold through misen.com. Its own partnerships page routes creator/influencer applicants to its Misen Creator program and affiliate signups to Impact; no commission rate is published on any brand or network page fetched.', 'United States', 'published') returning id into bid;
