  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://Misen.com/pages/partnerships', 'official_site', 'affiliate', 'Misen''s own partnerships page fetched in full: ''We love connecting with creators and brands who share our passion for clean cookware'', creators/influencers are directed to apply to the Misen Creator program (via Upfluence), and ''If you are interested in learning more about our affiliate program, sign up here'' — with the affiliate signup link routing to app.impact.com, confirming the program runs on Impact. The brand publishes NO commission percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://Misen.com/pages/partnerships', 'listing', 'affiliate', 'Rate note: Shopper''s generic 5-10% payout figure for Misen is a boilerplate directory number, not a brand- or network-published rate, and is NOT credited; a Sovrn merchant page likewise could not verify any rate. Because no fetched brand or network source publishes a percentage, commission_rate is null. No earnings-cap statement is published, so the cap is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 8, 10, 8, 4, '{"compensation": "No commission rate is published on any fetched brand or network source, so compensation is scored low on transparency; no cap statement exists", "contact_access": "Both the creator application and the affiliate signup are routed from the brand''s own partnerships page; no direct email is published", "credibility": "Established DTC kitchenware brand with a published partnerships page; rate transparency is the weak point", "niche_fit": "Knives and cookware are a staple of cooking-demo and knife-skills UGC, with strong sharpness and sear-test angles", "opportunity_availability": "Open creator application and Impact affiliate signup from the brand''s own page", "ugc_evidence": "The brand''s own partnerships page runs both a named creator program and an affiliate program \u2014 direct creator-facing evidence"}'::jsonb);
